fn debug_abort() {
    let mut force_unsafe_continue = 0u8;
    unsafe { write_volatile(&mut force_unsafe_continue, 0) };
    debug_pause();
    let f = unsafe { read_volatile(&force_unsafe_continue) };
    if f != 0 {
        return;
    } else {
        abort();
    }
}
```

