messages.en:
Maybe we can add a new marker type in `std` for specifying that sub-object provenance shouldn't apply:
```rust
#[lang = "phantom_no_subobject_provenance"]
pub struct PhantomNoSubobjectProvenanceBikeshed;
```

and then your `Header` struct can just be:
```rust
#[repr(C)]
pub struct Header {
    pub field1: Cell<u32>,
    pub field2: Cell<f64>,
    // unsafe so we don't need unsafe functions to access the header
    unsafe _pnsp: PhantomNoSubobjectProvenanceBikeshed,
}

#[repr(C)]
struct BiggerStruct {
    before_header: u8,
    header: Header,
    after_header: u8,
}

impl Header {
    fn as_bigger_struct(&self) -> &BiggerStruct {
        // safety: only way to make Header is inside BiggerStruct
        unsafe { &*(&raw const *self).byte_sub(offset_of!(BiggerStruct, header)).cast() }
    }
    pub fn before_header(&self) -> u8 {
        self.as_bigger_struct().before_header
    }
    pub fn after_header(&self) -> u8 {
        self.as_bigger_struct().after_header
    }
    pub fn new(buf: &mut [MaybeUninit<u8>]) -> &Header {
        let bigger_struct: &mut [MaybeUninit<BiggerStruct>] = unsafe { buf.align_to_mut().1 };
        let bigger_struct = bigger_struct[0].write(unsafe {
            BiggerStruct {
                before_header: 1,
                header: Header {
                    field1: Cell::new(3),
                    field2: Cell::new(4.0),
                    _pnsp: PhantomNoSubobjectProvenanceBikeshed,
                },
                after_header: 2,
            }
        });
        &bigger_struct.header
    }
}
```

