fn source(x: usize) {
    {
        let y = expensive_pure_computation(x);
        use_y(&y); // potentially side-effectfull
    }
    // probably allocates memory and deallocates it again before return
    something_unrelated();
    {
        // unfortunately we forgot `y`, so we have to recompute it
        let y = expensive_pure_computation(x);
        use_y_again(&y);
    }
}

fn target(x: usize) {
    let y = expensive_pure_computation(x);
    use_y(&y);
    // now called in a state where there is less free address space available
    something_unrelated();
    // reuse the `y` we previously had
    use_y_again(&y);
}
```

